{"implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_map = {n['id']: n for n in nodes}
    children = {}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
        else:
            children.setdefault(n['parent'], []).append(n['id'])
    retained = []
    visit = []
    def dfs(node_id, parent_retained):
        n = node_map[node_id]
        if not parent_retained:
            is_retained = False
        else:
            if n['removable']:
                is_retained = n['utility'] >= threshold
            else:
                is_retained = True
        if is_retained:
            retained.append(node_id)
            visit.append(node_id)
            for child in children.get(node_id, []):
                dfs(child, is_retained)
    dfs(root_id, True)
    return {'retained_node_ids': retained, 'visit_order': visit}"}
